def initial_partitions(apps, schema_editor):
    """Yesterday to 7 days ahead; afterwards the beat task keeps them ahead."""
    today = datetime.now(UTC).date()
    with schema_editor.connection.cursor() as cur:
        for offset in range(-1, 8):
            day = today + timedelta(days=offset)
            for table, start, step in (
                ("intel_signal_event", day, 1),
                ("intel_user_item_engagement", day - timedelta(days=day.weekday()), 7),
            ):
                lo = datetime(start.year, start.month, start.day, tzinfo=UTC)
                hi = lo + timedelta(days=step)
                cur.execute(
                    f"CREATE TABLE IF NOT EXISTS {table}_p{start:%Y%m%d} PARTITION OF {table} "
                    f"FOR VALUES FROM ('{lo.isoformat()}') TO ('{hi.isoformat()}')"
                )


